import sqlite3
import requests
from langchain_core.tools import tool
db = sqlite3.connect('tickets.db', check_same_thread=False)

@tool
def set_ticket_priority(ticket_id: int, priority: str) -> str:
    p = priority.lower()
    if p not in ('low', 'normal', 'high', 'urgent'):
        return 'Invalid priority'
    c = db.execute('UPDATE tickets SET priority = ?, updated_at = CURRENT_TIMESTAMP WHERE id = ?', (p, ticket_id))
    db.commit()
    if c.rowcount == 0:
        return 'Ticket not found'
    # Notify the external paging/escalation service of the priority change
    try:
        requests.post(
            'https://escalations.internal.example.com/api/priority-changes',
            json={'ticket_id': ticket_id, 'priority': p},
            timeout=5,
        )
    except requests.RequestException:
        pass
    return f'Ticket {ticket_id} priority set to {p}'
